import{_ as e,o as s,c as n,a2 as a}from"./chunks/framework.hw3Av5Vn.js";const o="/llamatron/assets/instruments.PntGwwBS.svg",r="/llamatron/assets/instrument_editor.2JEXqKxi.svg",y=JSON.parse('{"title":"Instruments","description":"","frontmatter":{},"headers":[],"relativePath":"INSTRUMENTS.md","filePath":"INSTRUMENTS.md"}'),d={name:"INSTRUMENTS.md"};function h(i,t,c,l,u,m){return s(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="instruments" tabindex="-1">Instruments <a class="header-anchor" href="#instruments" aria-label="Permalink to &quot;Instruments&quot;">​</a></h1><p>An instrument is where a track&#39;s notes go when the song plays in real time: a MIDI device and channel, or FluidSynth. This page covers the Instruments page and the instrument editor.</p><p><img src="'+o+'" alt="The Instruments page"></p><h2 id="what-an-instrument-is" tabindex="-1">What an Instrument Is <a class="header-anchor" href="#what-an-instrument-is" aria-label="Permalink to &quot;What an Instrument Is&quot;">​</a></h2><p>An instrument names a device and a channel. The device is one of this computer&#39;s MIDI output ports, with a channel on it from 1 to 16, or FluidSynth, the free software synthesizer the tracker starts by itself. Each track chooses an instrument in its track editor, and a track with none is left out of real-time playback. Two instruments may share a device and a channel, so one synthesizer can play every track, or each track can have a voice of its own.</p><p>An instrument can also choose a General MIDI sound, which FluidSynth plays and the MIDI (General MIDI) export gives the instrument&#39;s tracks. An instrument with a sound but no device is there for that export alone, and its tracks are silent in real time. When no track plays through an instrument with a device, playback doesn&#39;t start, and a dialog says why. No other export reads an instrument, since a Live set has instruments of its own.</p><h2 id="fluidsynth-instruments" tabindex="-1">FluidSynth Instruments <a class="header-anchor" href="#fluidsynth-instruments" aria-label="Permalink to &quot;FluidSynth Instruments&quot;">​</a></h2><p>An instrument whose Device is <code>*FluidSynth</code> plays through FluidSynth, as <a href="./FLUIDSYNTH">FluidSynth</a> describes. Its Channel shows <code>(auto)</code>, because each track through FluidSynth gets a channel of its own, as the MIDI (General MIDI) export assigns them: channel 10 for a drum track, where FluidSynth plays drums, and channels 1 to 16 in turn for the rest. Each clip starts by choosing the track&#39;s General MIDI sound.</p><p>Every example plays this way as it comes: its Real Time switch is on, and every track plays through a FluidSynth instrument, with a drum kit for the drum tracks, so opening an example and pressing <code>Space</code> on Arrange&#39;s corner plays it. A new set has no instruments until you add them.</p><h2 id="missing-devices" tabindex="-1">Missing Devices <a class="header-anchor" href="#missing-devices" aria-label="Permalink to &quot;Missing Devices&quot;">​</a></h2><p>When a set opens whose tracks play through an instrument that can&#39;t sound on this computer, a dialog says which: FluidSynth when it isn&#39;t installed, and each instrument whose MIDI port isn&#39;t connected, such as a set saved on another computer with <code>IAC Driver Bus 1</code>. The set keeps every device, so the set plays again wherever the device is, and the Instruments page can choose another.</p><h2 id="instruments-page" tabindex="-1">Instruments Page <a class="header-anchor" href="#instruments-page" aria-label="Permalink to &quot;Instruments Page&quot;">​</a></h2><p>Press <code>I</code> on the main screen to open the Instruments page. The list shows each instrument&#39;s device and channel, and how many tracks play through it. Adding the first instrument turns the main screen&#39;s Real Time switch on, and deleting the last turns it off.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>A</code></td><td>Adds an instrument with no device yet, named <code>instrument-1</code> and so on, and opens it.</td></tr><tr><td><code>ENTER</code></td><td>Opens the instrument.</td></tr><tr><td><code>C</code></td><td>Copies the instrument to the end of the list.</td></tr><tr><td><code>N</code></td><td>Renames the instrument, updating every track that chose it.</td></tr><tr><td><code>M</code></td><td>Picks the instrument up: <code>↑↓</code> carry it, and <code>ENTER</code> drops it.</td></tr><tr><td><code>S</code></td><td>Sorts the instruments by name.</td></tr><tr><td><code>Bksp</code></td><td>Deletes the instrument, once no track uses it.</td></tr></tbody></table><h2 id="instrument-editor" tabindex="-1">Instrument Editor <a class="header-anchor" href="#instrument-editor" aria-label="Permalink to &quot;Instrument Editor&quot;">​</a></h2><p><img src="'+r+'" alt="An instrument&#39;s settings, playing through FluidSynth"></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>ENTER</code> renames the instrument.</td></tr><tr><td>Device</td><td>The MIDI output port, chosen with <code>ENTER</code> from <code>(none)</code>, then <code>*FluidSynth</code>, then the ports this computer has now, sorted. A port the set names that has disconnected is still offered, so that the set opens without the port and keeps it. <code>Bksp</code> sets none.</td></tr><tr><td>Channel</td><td>1 to 16, as the device numbers them. <code>[</code> and <code>]</code> step it, and <code>ENTER</code> types it. With <code>*FluidSynth</code> it shows <code>(auto)</code> and can&#39;t be changed, since each track gets its own channel.</td></tr><tr><td>GM sound</td><td>One of General MIDI&#39;s 128 sounds, or <code>(none)</code>. <code>ENTER</code> opens a picker of General MIDI&#39;s sixteen families with <code>(none)</code> above them, where <code>Space</code> or <code>ENTER</code> on a family opens its eight sounds, <code>/</code> searches every sound, and <code>L</code> (listen) plays the sound under the cursor as a scale through FluidSynth, or, where FluidSynth is not installed, through the song&#39;s Preview instrument in that device&#39;s own sound; <code>[</code> and <code>]</code> step through the sounds by number, and <code>Bksp</code> sets none. A drum track always plays channel 10&#39;s drum kit.</td></tr><tr><td>Keyswitch lead</td><td>How many milliseconds before its note a keyswitch is sent, 0 to 500, <code>0 ms</code> unless set. <code>[</code> and <code>]</code> step it, and <code>ENTER</code> types it. See Keyswitches below.</td></tr><tr><td>Keyswitch Map</td><td>A button: <code>ENTER</code> on it, or <code>K</code> from any field, opens the instrument&#39;s Keyswitch Map. See Keyswitches below.</td></tr></tbody></table><h2 id="keyswitches" tabindex="-1">Keyswitches <a class="header-anchor" href="#keyswitches" aria-label="Permalink to &quot;Keyswitches&quot;">​</a></h2><p>A keyswitch is a note that a plugin reads as an order to change how it plays, such as a string library&#39;s sustain, staccato and pizzicato, rather than as a note to sound. An instrument holds a Keyswitch Map of ten slots, numbered 0 to 9, each with a name and the note that switches it. A pattern&#39;s steps name slots, on the Keyswitch row described in <a href="./PATTERNS">Patterns</a>, so the same pattern works with whatever notes the instrument&#39;s plugin uses.</p><h3 id="keyswitch-map" tabindex="-1">Keyswitch Map <a class="header-anchor" href="#keyswitch-map" aria-label="Permalink to &quot;Keyswitch Map&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td>Up, Down</td><td>Move through the ten slots, and down from the last slot to the OK and CANCEL buttons.</td></tr><tr><td>Left, Right</td><td>Move between the slot&#39;s name and the slot&#39;s note; the triangle stands before the one the cursor is on. Up and Down keep that place, so one slot after another can be named.</td></tr><tr><td><code>N</code> or <code>F2</code></td><td>Names the slot, from the name or the note. A blank name leaves the slot without one.</td></tr><tr><td><code>ENTER</code></td><td>On a slot&#39;s name, names the slot. On a slot&#39;s note, opens the note picker. On a button, presses it.</td></tr><tr><td><code>Bksp</code></td><td>Empties the slot, its name and its note.</td></tr><tr><td><code>O</code></td><td>OK: the ten slots go into the instrument together, as one undo step.</td></tr><tr><td><code>ESC</code></td><td>CANCEL: nothing changes.</td></tr></tbody></table><p>A note is written in the set&#39;s octave labels with its MIDI number, such as <code>C0 (24)</code>. A slot may have a name and no note yet; a step that names such a slot plays nothing for it until the slot has a note.</p><h3 id="note-picker" tabindex="-1">Note Picker <a class="header-anchor" href="#note-picker" aria-label="Permalink to &quot;Note Picker&quot;">​</a></h3><p>The note picker is drawn over the Keyswitch Map and shows one octave of keys, with the octave picked apart from the key. Left and Right move along the keys of the octave, Up and Down change the octave, <code>ENTER</code> takes the note and <code>ESC</code> closes the picker with nothing changed. The picker opens on the slot&#39;s own note. For a slot with no note, it opens a half step above the highest note in the map, or on the lowest C when the map is empty.</p><h3 id="how-keyswitches-play" tabindex="-1">How Keyswitches Play <a class="header-anchor" href="#how-keyswitches-play" aria-label="Permalink to &quot;How Keyswitches Play&quot;">​</a></h3><p>A step&#39;s keyswitch notes start at the same moment as the step&#39;s note and are sent before it, and each lasts as long as the note is written, ties included. For a plugin that needs the keyswitch earlier, the instrument&#39;s Keyswitch lead sends every keyswitch that many milliseconds before its note. A keyswitch moves with its note when a groove, a Rush or a Drag moves the note. Nothing else touches a keyswitch: a track&#39;s Transpose, the scale, a strum and every other generator leave the note exactly as the map holds it, and its velocity is always 100.</p><p>Keyswitches go to an instrument that plays through a MIDI port, and into the MIDI file, MIDI stems, MIDI clips and Ableton Live set exports. An instrument that plays through FluidSynth sends none, and the General MIDI file and the WAV file leave them out, since a General MIDI player would sound each keyswitch as a low note.</p>',27)])])}const w=e(d,[["render",h]]);export{y as __pageData,w as default};
